### Root cause

`HandleCreateRun` performed side effects in the wrong order:

1. create worktree on disk
2. insert `loop_state` row (status `running`)
3. (never) check that the loop exists

A bogus `loop_id` therefore produced a 202 with an orphan worktree and a `loop_state` row that could never transition to `stopped` or be inspected — a phantom run.

### Fix strategy

**Validate loop existence before any side effects.** A loop is valid iff either:

- it exists in the workspace spec (`.ralph.yaml` via `LoadRalphSpec`, covering **enabled, disabled, and manual** loops — any named loop is runnable), **or**
- a `loop_state` row from a prior accepted run already references it (spec-drift fallback: the loop was removed from `.ralph.yaml` after a previous run; we must not strand that state).

Unknown loops return **404** with the shared const `StrLoopNotFound`. Rejected requests create **no worktree and no state rows**.

---

### 1. Shared error constant + sentinel (new file `internal/runs/errors.go`)

```go
package runs

import "errors"

// StrLoopNotFound is the shared, stable message returned by the API and
// matched by clients. It is also the text of the sentinel error below.
const StrLoopNotFound = "loop not found"

// ErrLoopNotFound is the sentinel used internally so handlers can map it to
// HTTP 404 without string-matching.
var ErrLoopNotFound = errors.New(StrLoopNotFound)
```

### 2. Spec loader returns ALL loops (new file `internal/ralph/loader.go`)

```go
package ralph

// Loop is one entry from .ralph.yaml. Disabled and manual loops are still
// first-class named loops: they can be run, just not by the scheduler/manual
// gate respectively. The API only cares about existence here.
type Loop struct {
    ID      string `yaml:"id"`
    Name    string `yaml:"name"`
    Command string `yaml:"command"`
    Enabled *bool  `yaml:"enabled"` // nil => enabled (default)
    Manual  bool   `yaml:"manual"`
}

type Spec struct {
    Loops map[string]*Loop
    Order []string
}

// Loop resolves any loop by exact ID — enabled, disabled, or manual.
func (s *Spec) Loop(id string) (*Loop, bool) {
    l, ok := s.Loops[id]
    return l, ok
}

// LoadRalphSpec parses dir/.ralph.yaml. Every loop declared in the file is
// indexed regardless of enabled/manual so validation is purely about existence.
func LoadRalphSpec(dir string) (*Spec, error) {
    raw, err := os.ReadFile(filepath.Join(dir, ".ralph.yaml"))
    if err != nil {
        return nil, fmt.Errorf("read .ralph.yaml: %w", err)
    }
    var doc struct {
        Loops []*Loop `yaml:"loops"`
    }
    if err := yaml.Unmarshal(raw, &doc); err != nil {
        return nil, fmt.Errorf("parse .ralph.yaml: %w", err)
    }
    s := &Spec{Loops: make(map[string]*Loop, len(doc.Loops))}
    for _, l := range doc.Loops {
        if l.ID == "" {
            return nil, fmt.Errorf(".ralph.yaml: loop with empty id")
        }
        if _, dup := s.Loops[l.ID]; dup {
            return nil, fmt.Errorf(".ralph.yaml: duplicate loop id %q", l.ID)
        }
        s.Loops[l.ID] = l
        s.Order = append(s.Order, l.ID)
    }
    return s, nil
}
```

### 3. Pure validation, no writes (new method in `internal/runs/service.go`)

```go
// ResolveLoop is a read-only gate called BEFORE worktree creation and state
// insertion. It returns ErrLoopNotFound for loops that exist nowhere.
func (s *Service) ResolveLoop(ctx context.Context, ws *workspace.Workspace, loopID string) (*ralph.Loop, error) {
    spec, err := ralph.LoadRalphSpec(ws.Path)
    if err != nil {
        // A broken spec is a workspace problem, not "loop not found":
        // surface it as-is so the caller can return 422/500, never 404.
        return nil, fmt.Errorf("load spec for workspace %s: %w", ws.ID, err)
    }
    if l, ok := spec.Loop(loopID); ok {
        return l, nil // enabled, disabled, or manual — all resolvable
    }
    // Spec-drift fallback: the loop was previously accepted (a loop_state row
    // exists). Keep it runnable so existing state stays inspectable/stop-able.
    hasPrior, err := s.store.HasPriorRun(ctx, ws.ID, loopID)
    if err != nil {
        return nil, err
    }
    if hasPrior {
        return nil, nil // valid via fallback; no spec entry needed
    }
    return nil, ErrLoopNotFound
}
```

`HasPriorRun` is a pure SELECT (no side effects):

```go
// store.go
func (s *Store) HasPriorRun(ctx context.Context, workspaceID, loopID string) (bool, error) {
    const q = `SELECT EXISTS(SELECT 1 FROM loop_state WHERE workspace_id=$1 AND loop_id=$2)`
    var ok bool
    err := s.db.QueryRowContext(ctx, q, workspaceID, loopID).Scan(&ok)
    return ok, err
}
```

### 4. Handler: validate → worktree → state (patch `internal/api/run.go`)

```go
func (s *Server) CreateRun(w http.ResponseWriter, r *http.Request) {
    var req CreateRunRequest
    if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
        writeError(w, http.StatusBadRequest, StrInvalidBody)
        return
    }
    ws, err := s.workspaces.Get(r.Context(), chi.URLParam(r, "workspaceID"))
    if err != nil {
        writeError(w, http.StatusNotFound, StrWorkspaceNotFound)
        return
    }

    // DOGFOOD-004: validate loop existence BEFORE any side effect.
    if _, err := s.runs.ResolveLoop(r.Context(), ws, req.LoopID); err != nil {
        switch {
        case errors.Is(err, ErrLoopNotFound):
            writeError(w, http.StatusNotFound, StrLoopNotFound)
        case errors.Is(err, ralph.ErrSpec):
            writeError(w, http.StatusUnprocessableEntity, StrInvalidSpec)
        default:
            writeError(w, http.StatusInternalServerError, StrInternalError)
        }
        return
    }

    // Only now create the worktree and the loop_state row.
    wt, err := s.worktrees.Create(r.Context(), ws, req)
    if err != nil {
        writeError(w, http.StatusInternalServerError, StrWorktreeFailed)
        return
    }
    st, err := s.state.StartRun(r.Context(), ws.ID, req.LoopID, wt)
    if err != nil {
        // Clean up the worktree if state insertion fails so we never leave
        // an orphan on the other side either.
        _ = s.worktrees.Remove(r.Context(), wt)
        writeError(w, http.StatusInternalServerError, StrStateFailed)
        return
    }
    writeJSON(w, http.StatusAccepted, RunResponse{
        RunID:  st.ID,
        LoopID: req.LoopID,
        Status: st.Status, // "running"
    })
}
```

### 5. Regression test (new file `internal/api/run_test.go`)

```go
func newTestWorkspace(t *testing.T, ralphYAML string) *workspace.Workspace {
    t.Helper()
    dir := t.TempDir()
    if ralphYAML != "" {
        if err := os.WriteFile(filepath.Join(dir, ".ralph.yaml"), []byte(ralphYAML), 0o644); err != nil {
            t.Fatal(err)
        }
    }
    return &workspace.Workspace{ID: "ws-1", Path: dir}
}

const threeLoopsYAML = `
loops:
  - id: known-loop
    command: echo hi
  - id: disabled-loop
    command: echo bye
    enabled: false
  - id: manual-loop
    command: echo manual
    manual: true
`

func worktreeDirs(t *testing.T, ws *workspace.Workspace) []string {
    t.Helper()
    ents, err := os.ReadDir(filepath.Join(ws.Path, "worktrees"))
    if errors.Is(err, fs.ErrNotExist) {
        return nil
    }
    if err != nil {
        t.Fatal(err)
    }
    var dirs []string
    for _, e := range ents {
        if e.IsDir() {
            dirs = append(dirs, e.Name())
        }
    }
    return dirs
}

// DOGFOOD-004: unknown loop => 404, no worktree, zero loop_state rows.
func TestCreateRun_RejectsUnknownLoop_NoSideEffects(t *testing.T) {
    ws := newTestWorkspace(t, threeLoopsYAML)
    store := newMemoryStore(t)
    srv := newTestServer(t, ws, store)

    resp := srv.POST("/v1/workspaces/"+ws.ID+"/runs").
        WithJSON(map[string]string{"loop_id": "ghost-loop"}).
        Expect(t).
        Status(http.StatusNotFound).
        BodyContains(StrLoopNotFound)

    _ = resp // resp used for explicit assertion readability
    if dirs := worktreeDirs(t, ws); len(dirs) != 0 {
        t.Fatalf("worktree created for unknown loop: %v", dirs)
    }
    if n := store.CountLoopStates(ws.ID); n != 0 {
        t.Fatalf("loop_state rows created for unknown loop: %d", n)
    }
}

// Known, disabled, and manual loops still get 202.
func TestCreateRun_AcceptsKnownDisabledManual(t *testing.T) {
    for _, id := range []string{"known-loop", "disabled-loop", "manual-loop"} {
        t.Run(id, func(t *testing.T) {
            ws := newTestWorkspace(t, threeLoopsYAML)
            store := newMemoryStore(t)
            srv := newTestServer(t, ws, store)

            srv.POST("/v1/workspaces/"+ws.ID+"/runs").
                WithJSON(map[string]string{"loop_id": id}).
                Expect(t).Status(http.StatusAccepted)

            if dirs := worktreeDirs(t, ws); len(dirs) != 1 {
                t.Fatalf("expected exactly 1 worktree, got %v", dirs)
            }
            if row := store.LoopState(ws.ID, id); row == nil {
                t.Fatalf("expected loop_state row for %q", id)
            }
        })
    }
}

// Spec-drift fallback: loop removed from .ralph.yaml after a prior run stays
// runnable (and its state stays inspectable), never 404.
func TestCreateRun_PriorStateFallback_AllowsSpecDriftedLoop(t *testing.T) {
    ws := newTestWorkspace(t, threeLoopsYAML)
    store := newMemoryStore(t)
    store.SeedRun(ws.ID, "known-loop", "run-1") // prior accepted run

    // Now the spec no longer declares known-loop.
    ws.Path = newTestWorkspace(t, `
loops:
  - id: disabled-loop
    command: echo bye
    enabled: false
`).Path

    srv := newTestServer(t, ws, store)
    srv.POST("/v1/workspaces/"+ws.ID+"/runs").
        WithJSON(map[string]string{"loop_id": "known-loop"}).
        Expect(t).Status(http.StatusAccepted)

    if row := store.LoopState(ws.ID, "known-loop"); row == nil {
        t.Fatal("expected new loop_state row via prior-run fallback")
    }
}
```

